if multiple:
    fac = factorint(n, limit=limit, use_trial=use_trial,
                       use_rho=use_rho, use_pm1=use_pm1,
                       verbose=verbose, visual=False, multiple=False)
    factorlist = sum(([p] * fac[p] if fac[p] > 0 else [S.One/p]*(-fac[p])
                           for p in sorted(fac)), [])
    return factorlist

factordict = {}
